package dev.gamersclt.batcaverna.nativeapp;
import android.content.Context;
import android.widget.*;
import org.json.*;
/** Real images saved to the account; uploads go through existing moderation. */
final class StickerSheet {
 interface Selection {void accept(JSONObject sticker);}
 static void show(Context c,Selection selected){NativeSheet sheet=new NativeSheet(c,"Suas figurinhas");TextView state=NativeSheet.text(c,"Carregando…",13,0xffb6a7cc);sheet.body.addView(state);Button add=new Button(c);add.setText("+ Adicionar JPG, PNG ou WebP");AppStyle.button(add,false);sheet.body.addView(add);LinearLayout grid=new LinearLayout(c);grid.setOrientation(LinearLayout.VERTICAL);sheet.body.addView(grid);Runnable load=()->new AccountRepository(c).stickers((rows,error)->{if(!sheet.dialog.isShowing())return;grid.removeAllViews();state.setText(error!=null?error:rows.length()==0?"Você ainda não tem figurinhas nesta conta.":rows.length()+" figurinhas");if(error!=null)return;LinearLayout row=null;for(int i=0;i<rows.length();i++){if(i%3==0){row=new LinearLayout(c);grid.addView(row);}JSONObject item=rows.optJSONObject(i);if(item==null)continue;ImageView image=new ImageView(c);image.setScaleType(ImageView.ScaleType.CENTER_INSIDE);image.setContentDescription(item.optString("name","Figurinha"));row.addView(image,new LinearLayout.LayoutParams(0,NativeSheet.dp(c,100),1));AccountImageLoader.load(image,BuildConfig.SUPABASE_URL+"/storage/v1/object/public/chat-media/"+item.optString("path"));image.setOnClickListener(v->{sheet.dialog.dismiss();selected.accept(item);});}if(row!=null&&rows.length()%3!=0)for(int i=rows.length()%3;i<3;i++)row.addView(new android.view.View(c),new LinearLayout.LayoutParams(0,1,1));});add.setOnClickListener(v->((MainActivity)c).chooseStickerImage(uri->{if(!sheet.dialog.isShowing())return;NativeSheet confirm=new NativeSheet(c,"Salvar figurinha");confirm.body.addView(NativeSheet.text(c,"A imagem passará pela moderação antes de ser salva na conta.",14,0xffc4b8d5));EditText name=NativeSheet.input(c,"Nome da figurinha",80);name.setText("Minha figurinha");confirm.body.addView(name);TextView feedback=NativeSheet.text(c,"",13,0xffc4b8d5);confirm.body.addView(feedback);Button save=new Button(c);save.setText("Salvar na conta");AppStyle.button(save,true);confirm.body.addView(save);save.setOnClickListener(w->{if(name.getText().toString().trim().isEmpty()){feedback.setText("Informe um nome.");return;}save.setEnabled(false);confirm.busy(true);feedback.setText("Verificando e salvando…");new AccountRepository(c).saveSticker(uri,name.getText().toString().trim(),(rows,e)->{confirm.busy(false);if(e!=null){feedback.setText(e+" Confira a coleção antes de reenviar.");return;}confirm.dialog.dismiss();load.run();});});confirm.show();}));sheet.show();load.run();}
}
